create table public.krim_customs_document_submissions (
 id bigint generated by default as identity primary key, customs_record_id bigint not null, shipment_id bigint not null,
 submitted_by_organization_id bigint not null references public.krim_organizations(id) on delete restrict,
 submitted_by_user_id uuid not null,
 document_type text not null check(document_type in ('commercial_invoice','packing_list','certificate_of_origin','import_permit','export_permit','bill_of_lading','air_waybill','road_consignment_note','insurance_certificate','product_certificate','dangerous_goods_declaration','customs_declaration','duty_payment_receipt','inspection_certificate','other')),
 document_reference text, issuing_country_id bigint references public.krim_countries(id), issued_at date, expires_at date,
 storage_path text not null, mime_type text not null check(mime_type in ('application/pdf','image/jpeg','image/png')),
 file_size bigint not null check(file_size between 1 and 10485760),
 status text not null default 'pending_review' check(status in ('pending_review','verified','rejected','superseded')),
 submitted_at timestamptz not null default now(), reviewed_by uuid, reviewed_by_organization_id bigint references public.krim_organizations(id),
 reviewed_at timestamptz, review_note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 constraint krim_customs_docs_customs_shipment_fk foreign key(customs_record_id,shipment_id) references public.krim_shipment_customs(id,shipment_id) on delete restrict,
 constraint krim_customs_docs_submitter_path_check check(storage_path like 'customs-docs/'||shipment_id::text||'/'||submitted_by_organization_id::text||'/'||submitted_by_user_id::text||'/%')
);
create index krim_customs_document_submissions_shipment_status_idx on public.krim_customs_document_submissions(shipment_id,status,submitted_at desc);
create index krim_customs_document_submissions_record_type_idx on public.krim_customs_document_submissions(customs_record_id,document_type,status);
alter table public.krim_customs_document_submissions enable row level security;
alter table public.krim_customs_document_submissions force row level security;
revoke all on public.krim_customs_document_submissions from public,anon,authenticated;
grant select on public.krim_customs_document_submissions to authenticated;
create policy "Customs shipment document scoped read" on public.krim_customs_document_submissions for select to authenticated using (
 exists(select 1 from public.krim_shipments s where s.id=shipment_id and private.krim_has_permission((select auth.uid()),s.customer_organization_id,'shipment.view'))
 or exists(select 1 from public.krim_customs_broker_assignments a where a.customs_record_id=krim_customs_document_submissions.customs_record_id and a.shipment_id=krim_customs_document_submissions.shipment_id and a.assignment_status='accepted' and private.krim_has_permission((select auth.uid()),a.broker_organization_id,'compliance.view'))
 or (coalesce(auth.jwt()->>'aal','aal1')='aal2' and private.krim_has_permission((select auth.uid()),1,'admin.platform'))
);
create table public.krim_customs_document_events (
 id bigint generated by default as identity primary key, submission_id bigint not null references public.krim_customs_document_submissions(id) on delete restrict,
 customs_record_id bigint not null, shipment_id bigint not null, event_type text not null check(event_type in ('submitted','verified','rejected','superseded')),
 actor_user_id uuid not null, actor_organization_id bigint references public.krim_organizations(id), event_note text not null default '', created_at timestamptz not null default now()
);
create index krim_customs_document_events_submission_idx on public.krim_customs_document_events(submission_id,created_at desc);
alter table public.krim_customs_document_events enable row level security;
alter table public.krim_customs_document_events force row level security;
revoke all on public.krim_customs_document_events from public,anon,authenticated;
grant select on public.krim_customs_document_events to authenticated;
create policy "Customs document event scoped read" on public.krim_customs_document_events for select to authenticated using (
 exists(select 1 from public.krim_customs_document_submissions d join public.krim_shipments s on s.id=d.shipment_id
 where d.id=krim_customs_document_events.submission_id and (
 private.krim_has_permission((select auth.uid()),s.customer_organization_id,'shipment.view')
 or exists(select 1 from public.krim_customs_broker_assignments a where a.customs_record_id=d.customs_record_id and a.shipment_id=d.shipment_id and a.assignment_status='accepted' and private.krim_has_permission((select auth.uid()),a.broker_organization_id,'compliance.view'))))
 or (coalesce(auth.jwt()->>'aal','aal1')='aal2' and private.krim_has_permission((select auth.uid()),1,'admin.platform'))
);